solution.solution.cpp:
#include <cstdint>
#include <map>
#include <optional>
#include <string>
#include <vector>

struct Done { std::uint32_t id; std::string method; std::string outcome; };

class PendingRequests
{
public:
    explicit PendingRequests(std::uint32_t maxInFlight) : limit{ maxInFlight } {}

    std::optional<std::uint32_t> send(const std::string& method, std::uint64_t now, std::uint64_t timeout)
    {
        if (pending.size() >= limit) return std::nullopt;
        const std::uint32_t id{ next++ };
        pending[id] = { method, now + timeout };
        return id;
    }

    std::optional<Done> response(std::uint32_t id, const std::string& result)
    {
        const auto it{ pending.find(id) };
        if (it == pending.end()) return std::nullopt;
        Done d{ id, it->second.method, result };
        pending.erase(it);
        return d;
    }

    std::vector<Done> expire(std::uint64_t now)
    {
        std::vector<Done> out;
        for (auto it{ pending.begin() }; it != pending.end();)
        {
            if (it->second.deadline <= now) { out.push_back({ it->first, it->second.method, "timeout" }); it = pending.erase(it); }
            else ++it;
        }
        return out;
    }

    std::vector<Done> connectionLost()
    {
        std::vector<Done> out;
        for (const auto& [id, p] : pending) out.push_back({ id, p.method, "connection lost" });
        pending.clear();
        return out;
    }

    std::size_t inFlight() const { return pending.size(); }

private:
    struct Pending { std::string method; std::uint64_t deadline; };
    std::uint32_t limit;
    std::uint32_t next{ 1 };
    std::map<std::uint32_t, Pending> pending;
};

unitTests:
TEST("ids and responses in any order") {
    PendingRequests p{ 8 };
    const auto a{ p.send("findSymbol", 1000, 5000) }, b{ p.send("formatFile", 1002, 5000) }, c{ p.send("ping", 1003, 5000) };
    CHECK_EQ(a.value_or(0), 1u); CHECK_EQ(b.value_or(0), 2u); CHECK_EQ(c.value_or(0), 3u);
    const auto done{ p.response(3, "pong") };
    CHECK(done.has_value());
    if (done) { CHECK_EQ(done->method, std::string("ping")); CHECK_EQ(done->outcome, std::string("pong")); }
    CHECK(!p.response(3, "again").has_value());
    CHECK(!p.response(77, "bogus").has_value());
    CHECK_EQ(p.inFlight(), 2u);
}
TEST("timeouts") {
    PendingRequests p{ 8 };
    p.send("slow", 0, 100);
    p.send("fast", 50, 10);
    p.send("later", 60, 1000);
    const auto expired{ p.expire(100) };
    CHECK_EQ(expired.size(), 2u);
    if (expired.size() == 2) { CHECK_EQ(expired[0].id, 1u); CHECK_EQ(expired[1].method, std::string("fast")); CHECK_EQ(expired[0].outcome, std::string("timeout")); }
    CHECK(!p.response(1, "too late").has_value());
    CHECK(p.expire(500).empty());
    CHECK_EQ(p.inFlight(), 1u);
}
TEST("limits and lost connections") {
    PendingRequests p{ 2 };
    CHECK(p.send("a", 0, 10).has_value());
    CHECK(p.send("b", 0, 10).has_value());
    CHECK(!p.send("c", 0, 10).has_value());
    const auto lost{ p.connectionLost() };
    CHECK_EQ(lost.size(), 2u);
    if (lost.size() == 2) CHECK_EQ(lost[1].outcome, std::string("connection lost"));
    CHECK_EQ(p.send("d", 0, 10).value_or(0), 3u);
}

